from pathlib import Path
import hashlib,json
P=Path(__file__).resolve().parent;S=P.parent/'clock-v13-component-candidate-v1'
def read(p):return json.loads(Path(p).read_bytes())
def row(p):
 p=Path(p);b=p.read_bytes();return dict(path=str(p),sha256=hashlib.sha256(b).hexdigest(),bytes=len(b))
def write(n,v):(P/n).write_text(json.dumps(v,indent=2)+'\n')
c=read(P/'checks.json');refs=read(S/'references.json');own=c['sourceIndex'];assert row(S/'index.json')==own
for m in read(own['path'])['files']:assert row(S/m['path'])==dict(m,path=str(S/m['path']))
grammar=read(S/'grammar.terminal.json');assert grammar['source']==row(S/'build.mjs')and grammar['argv']==[refs['node']['path'],'--check',str(S/'build.mjs')]and grammar['executable']==refs['node']and grammar['rawExitCode']==0
fixed=dict(read(S/'future-source-review-contract.json'),componentSourceIndexSha256=own['sha256'])
inputs=dict(sourceIndex=own,entry=row(S/'build.mjs'),inputManifest=row(S/'source-inputs.json'),references=row(S/'references.json'),nativePreflight=refs['nativePreflight'],nativePreflightFamily=refs['nativePreflightFamily'],nativeConsumedInputs=refs['nativeConsumedInputs'],nativeEngine=refs['nativeEngine'],nativeMetadata=refs['nativeMetadata'],nativePins=refs['nativePins'],nativeSelector=refs['nativeSelector'],loaderSourceIndex=refs['loaderSourceIndex'],loaderEntry=refs['loaderEntry'],loaderSourcePeer=refs['loaderSourcePeer'],prunedAdapter=refs['prunedAdapter'],guest=refs['guest'],bundle=refs['bundle'],originalGuest=refs['originalGuest'],originalBundle=refs['originalBundle'],originalBundleGraph=refs['originalBundleGraph'],wit=refs['wit'],futureRuntimeRequirements=row(S/'future-full-clock-runtime-requirements.json'),futureExternalControllerContract=row(S/'future-external-controller-contract.json'),grammarEvidence=row(S/'grammar.terminal.json'),pureEvidence=row(S/'pure-results.json'))
r=dict(fixed,verifiedPassed=True,requiredExactInputs=inputs,coverage=c,checks=row(P/'checks.json'),selectedInterfaces=refs['selectedInterfaces'],disableFeatures=refs['disableFeatures'],requiredNativeReadOnlyEnvironment=refs['requiredNativeReadOnlyEnvironment'],nativeSourceRoot=refs['nativeSourceRoot'],nativeEmbeddingSourceRoot=refs['nativeEmbeddingSourceRoot'],actualPreflightOrLoaderInvoked=False,oldPackageImportedBeforeNewLoader=False,reviewerNodeOrPackageOrToolInvoked=False,nativeAdmissionAndPackagingRolesSeparate=True,metadataProjected=False,allSevenFutureResourceCasesPreserved=True,fullClockProfileAcceptance=False,originalBundleByteExact=True,originalGuestByteExact=True,actualExternalControllerImplementedInSource=False,actualExternalControllerRequired=True,primaryAndFinalProtectionPathsReviewed=True,actualArtifactReviewRequired=True,actualRootAuthority=None,actualRuntimeAuthority=None,operationalAdmission=False,runtimeAcceptanceClaim=False,grantsAnyActionAuthority=False,concreteBlockers=[],limitations=['Source/model/grammar evidence is not genuine native preflight, package initialization, component/Wizer or guest behavior.','Actual external original monitor, paired Root authorities, clean environment/TMP and full raw terminal/cleanup are separate future requirements.','Selected loader performs final audit before returning: an audit failure can leave no bytes for caller, remains failed/unaccepted and does not widen policy.','ReactDOM probe does not complete the full seven-case clock/resource profile or Next.js runtime compatibility.','No generated import, ordinary exports, key/crypto/unsafe prototype/reset/GC/lifecycle reuse/ALS/performance/security-complete/adoption authority.'])
write('results.json',r)
write('result-contract.json',dict(schemaVersion=1,requiredFixedValues=fixed,results=row(P/'results.json'),requiredExactInputs=inputs,selectedInterfaces=refs['selectedInterfaces'],requiredNativeReadOnlyEnvironment=refs['requiredNativeReadOnlyEnvironment'],externalOwnedNodeDeadlineSeconds=1800,externalWholePhaseDeadlineSeconds=2400,actualArtifactAndExternalRawReviewRequired=True,grantsAnyActionAuthority=False))
write('review-receipt.json',dict(schemaVersion=1,results=row(P/'results.json'),contract=row(P/'result-contract.json'),checks=row(P/'checks.json'),sourceIndex=own,ownerSourceUnchanged=True,ownerActionsInvoked=False))
files=[]
for p in sorted(P.iterdir()):
 if p.name!='index.json':r=row(p);r['path']=p.name;files.append(r)
write('index.json',dict(schemaVersion=1,files=files))
for n in ['index.json','results.json','result-contract.json','review-receipt.json']:print(json.dumps(row(P/n)))
